import * as THREE from 'three';
import {
  WEAPON_ATTACHMENT_TYPES, inspectWeaponHierarchy, validateWeaponProject,
  createWeaponGuide, weaponGuideHelper, disposeWeaponGuideHelper,
} from './weapon-attachments.js';

/**
 * M2b: non-destructive weapon guides inside the existing Weapon Studio.
 * No native GTA bones, metadata, or YFT/YDR are generated by this panel.
 */
export function mountWeaponAttachments({ layout, assembly, scene, invalidate, download, getReference, getName, toast }) {
  const panel = document.createElement('details');
  panel.className = 'wd-attachments';
  panel.innerHTML = `<summary>Weapon skeleton & attachment guides (M2b)</summary>
    <p class="muted">Inspects imported bones and named parts. Manual guides are preview-only, not native GTA weapon bones or attachment bindings.</p>
    <button type="button" data-wa-inspect>Inspect model hierarchy</button>
    <pre data-wa-hierarchy aria-live="polite"></pre>
    <label>Guide type<select data-wa-type>${WEAPON_ATTACHMENT_TYPES.map(type => '<option>' + type + '</option>').join('')}</select></label>
    <button type="button" data-wa-add>Add guide at selected part</button>
    <label>Guide<select data-wa-select></select></label>
    <div data-wa-fields>
      ${['X','Y','Z'].map((axis,i) => '<label>Position ' + axis + '<input type="number" step="0.001" min="-1000" max="1000" data-wa-pos="' + i + '"></label>').join('')}
      ${['X','Y','Z'].map((axis,i) => '<label>Rotation ' + axis + ' (degrees)<input type="number" step="1" min="-360" max="360" data-wa-rot="' + i + '"></label>').join('')}
    </div>
    <button type="button" data-wa-remove>Remove selected guide</button>
    <label><input type="checkbox" data-wa-show checked> Show guides in viewport</label>
    <button type="button" data-wa-save>Save guide project JSON</button>
    <button type="button" data-wa-load>Load guide project JSON</button>
    <input data-wa-file type="file" accept=".json,application/json" hidden>
    <p data-wa-status class="muted" role="status">Guides do not modify source meshes or original GLB exports.</p>`;
  layout.querySelector('.wd-export').append(panel);
  const $ = name => panel.querySelector('[data-wa-' + name + ']');
  const overlay = new THREE.Group();
  overlay.name = 'DITASHA weapon guide overlay - not exported';
  scene.add(overlay);
  let guides = [];
  const status = message => { $('status').textContent = message; };
  const notify = message => { status(message); toast?.(message); };
  function refresh() {
    overlay.clear();
    // Dispose previously created helper geometry/materials, not source assets.
    for (const helper of [...overlay.userData.disposed || []]) disposeWeaponGuideHelper(helper);
    const created = guides.map(weaponGuideHelper);
    overlay.userData.disposed = created;
    created.forEach(helper => overlay.add(helper));
    overlay.visible = $('show').checked;
    $('select').replaceChildren(...guides.map(guide => {
      const option = document.createElement('option');
      option.value = guide.id;
      option.textContent = guide.type + ' · ' + guide.name;
      return option;
    }));
    selectGuide(guides.at(-1)?.id);
    invalidate();
  }
  function selectGuide(id) {
    if (id) $('select').value = id;
    const selected = guides.find(guide => guide.id === $('select').value);
    for (let i=0;i<3;i++) {
      panel.querySelector('[data-wa-pos="' + i + '"]').value = selected?.position[i] ?? '';
      panel.querySelector('[data-wa-rot="' + i + '"]').value = selected?.rotation[i] ?? '';
    }
  }
  function current() { return guides.find(guide => guide.id === $('select').value); }
  $('inspect').onclick = () => {
    const data = inspectWeaponHierarchy(assembly);
    $('hierarchy').textContent = [
      'Imported bones: ' + data.bones.length,
      'Named attachment candidates: ' + data.candidates.length,
      ...data.bones.slice(0,64).map(item=>'Bone: ' + item.name + ' [' + item.parent + ']'),
      ...data.candidates.slice(0,64).map(item=>item.kind + ': ' + item.name),
      ...data.issues.map(issue=>'[' + issue.code + '] ' + issue.message),
      'Native bone IDs and GTA animation compatibility: NOT VERIFIED',
    ].join('\n');
    panel.open = true;
  };
  $('add').onclick = () => {
    const chosen = assembly.userData?.selectedWeaponPart;
    const base = new THREE.Vector3();
    const selected = chosen?.isObject3D ? chosen : assembly;
    selected.getWorldPosition(base);
    if (guides.length >= 32) return notify('Maximum 32 guides per weapon project.');
    const newGuide = createWeaponGuide($('type').value, base.toArray());
    guides.push(newGuide);
    refresh();
    status('Guide created. It is preview-only and cannot be exported as a GTA attachment yet.');
  };
  $('select').onchange = () => selectGuide();
  for (const [prefix, key] of [['pos', 'position'], ['rot', 'rotation']]) {
    for (let i=0;i<3;i++) {
      panel.querySelector('[data-wa-' + prefix + '="' + i + '"]').onchange = event => {
        const guide = current();
        if (!guide) return;
        const n = Number(event.target.value);
        const max = key === 'position' ? 1000 : 360;
        if (!Number.isFinite(n) || Math.abs(n)>max) {
          selectGuide(guide.id); return notify('Guide value exceeds safe limits.');
        }
        guide[key][i] = n;
        const keep = guide.id;
        refresh();
        selectGuide(keep);
      };
    }
  }
  $('remove').onclick = () => {
    const id = $('select').value;
    guides = guides.filter(guide => guide.id !== id);
    refresh();
  };
  $('show').onchange = () => { overlay.visible = $('show').checked; invalidate(); };
  $('save').onclick = async () => {
    try {
      const project = validateWeaponProject({
        schemaVersion: 1, name: getName(), reference: getReference()[1], guides,
      });
      const bytes = new TextEncoder().encode(JSON.stringify(project, null, 2));
      const result = await download(bytes, project.name + '.weapon-guides.json', 'application/json');
      if (result !== false) status('Saved attachment guide project (JSON), not native weapon data.');
    } catch (error) { notify(error.message); }
  };
  $('load').onclick = () => $('file').click();
  $('file').onchange = async () => {
    const file = $('file').files?.[0];
    $('file').value = '';
    if (!file) return;
    if (file.size > 32768) return notify('Guide project exceeds 32 KB limit.');
    try {
      const project = validateWeaponProject(JSON.parse(await file.text()));
      if (project.reference !== getReference()[1]) throw Error('Guide project weapon reference does not match selected model');
      guides = project.guides;
      refresh();
      status('Guide project loaded; existing model mesh and GLB export remain unchanged.');
    } catch (error) { notify('Guide import rejected: ' + error.message); }
  };
  function clearOnModelChange() {
    guides = [];
    refresh();
    $('hierarchy').textContent = '';
  }
  return { panel, clearOnModelChange, getGuides: () => guides.map(g => ({
    ...g, position: [...g.position], rotation: [...g.rotation],
  })) };
}
